import{_ as i,c as t,o as a,ah as n}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse(`{"title":"Jiao's Yi Lin","description":"Jiao's Yi Lin，整理自 App 的免費易經學習文檔。","frontmatter":{"title":"Jiao's Yi Lin","description":"Jiao's Yi Lin，整理自 App 的免費易經學習文檔。"},"headers":[],"relativePath":"en/articles/yilin/index.md","filePath":"en/articles/yilin/index.md"}`),o={name:"en/articles/yilin/index.md"};function s(r,e,h,l,m,d){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="jiao-s-yi-lin" tabindex="-1">Jiao&#39;s Yi Lin <a class="header-anchor" href="#jiao-s-yi-lin" aria-label="Permalink to “Jiao&#39;s Yi Lin”">​</a></h1><p><strong>Jiao&#39;s Yi Lin</strong> is a poetic divination text traditionally attributed to <strong>Jiao Yanshou</strong> of the Han dynasty, though the authorship is debated. It systematizes the combinations of the sixty-four hexagrams in the <em>I Ching</em>: <strong>each hexagram expands into sixty-four outcomes</strong>, creating <strong>64 × 64 = 4096</strong> oracle lines in total. The text is often written in <strong>four-character verse</strong>, turning abstract hexagram logic into vivid imagery and scenes.</p><h2 id="the-story-line-with-the-i-ching" tabindex="-1">The story line with the <em>I Ching</em> <a class="header-anchor" href="#the-story-line-with-the-i-ching" aria-label="Permalink to “The story line with the I Ching”">​</a></h2><p>The <em>I Ching</em> focuses on the structure of hexagrams and line statements, while <em>Yi Lin</em> works more like a corpus that turns hexagram meaning into readable poems:</p><ul><li>it supplements the hexagram with scenes, objects, movement, and outcomes</li><li>it makes divination easier to read as “image” and “moment”</li><li>it became an important source for later image-based and divinatory reading traditions</li></ul><h2 id="how-this-app-uses-yi-lin" tabindex="-1">How this app uses <em>Yi Lin</em> <a class="header-anchor" href="#how-this-app-uses-yi-lin" aria-label="Permalink to “How this app uses Yi Lin”">​</a></h2><p>When you cast a result, the app shows the matching poem for the “primary hexagram → changed hexagram” pair.</p><ol><li>First, pick up the key images in the poem.</li><li>Then compare them with your question and current situation.</li><li>Finally, return to the hexagram and moving line for a full reading.</li></ol><h2 id="translation-note" tabindex="-1">Translation note <a class="header-anchor" href="#translation-note" aria-label="Permalink to “Translation note”">​</a></h2><p>The English text is a direct, readable translation from the Chinese edition. The Chinese version remains primary; the English is for reference only.</p><ul><li>Reading order: image first, then question, then hexagram and moving line.</li><li>Source note: the English version is a direct translation from the Chinese <em>Jiao&#39;s Yi Lin</em> text and cannot fully convey the original nuance; use the Chinese as the authoritative text.</li></ul>',11)])])}const g=i(o,[["render",s]]);export{p as __pageData,g as default};
